import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.CCCdsIgc.js";const u=JSON.parse('{"title":"开发者工具与 PR","description":"","frontmatter":{},"headers":[],"relativePath":"guide/developer.md","filePath":"guide/developer.md"}'),d={name:"guide/developer.md"};function l(o,e,r,n,h,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="开发者工具与-pr" tabindex="-1">开发者工具与 PR <a class="header-anchor" href="#开发者工具与-pr" aria-label="Permalink to &quot;开发者工具与 PR&quot;">​</a></h1><p>给写程序的同事用。IT 在安全中心打开「<strong>开发者工具</strong>」后，办事模式多出这些能力（这类任务会用后台配置的编程模型）：</p><table tabindex="0"><thead><tr><th>工具</th><th>作用</th></tr></thead><tbody><tr><td><code>grep</code></td><td>按内容搜代码，支持 <code>**</code> 通配符</td></tr><tr><td><code>multi_edit</code></td><td>一次改一个文件里的多处</td></tr><tr><td><code>git_status</code> / <code>git_diff</code> / <code>git_log</code></td><td>查看状态、改动、历史</td></tr><tr><td><code>git_commit</code></td><td>提交</td></tr><tr><td><code>create_pull_request</code></td><td>推送当前分支并建 PR（每次都要你确认，不能从默认分支建）</td></tr><tr><td><code>pr_status</code> / <code>watch_pull_request</code></td><td>查 PR 状态 / 开始盯一个 PR</td></tr></tbody></table><p>输入框打 <code>/init</code>，AI 会读一遍项目，生成项目说明 <code>FLYKNIT.md</code>，以后的任务都会先参考它。</p><h2 id="git-操作的确认" tabindex="-1">git 操作的确认 <a class="header-anchor" href="#git-操作的确认" aria-label="Permalink to &quot;git 操作的确认&quot;">​</a></h2><p>按子命令和参数定级：查看类直接执行；提交按规则确认；<strong>推送、强制推送、删分支、丢弃修改</strong>等按高危每次确认。</p><h2 id="仓库面板" tabindex="-1">仓库面板 <a class="header-anchor" href="#仓库面板" aria-label="Permalink to &quot;仓库面板&quot;">​</a></h2><p>右侧「文件」标签上方显示当前仓库、分支、未提交改动、领先 / 落后的提交数：</p><ul><li>在 GitHub 上打开仓库或分支、复制分支名、新建或切换分支；</li><li>有未提交的改动或任务正在进行时不允许切换分支。</li></ul><h2 id="聊天里的-pr-链接" tabindex="-1">聊天里的 PR 链接 <a class="header-anchor" href="#聊天里的-pr-链接" aria-label="Permalink to &quot;聊天里的 PR 链接&quot;">​</a></h2><p>回答里出现 GitHub 的 PR 或 Issue 地址时，会显示成带图标的「#编号」。鼠标停在上面会弹出一张卡片，内容包括：</p><ul><li>状态：开放、草稿、已合并、已关闭；</li><li>仓库和编号、标题、作者；</li><li>PR 还显示增删行数和改了几个文件，Issue 显示评论数。</li></ul><p>卡片内容用你电脑上的 <code>gh</code> 查询。没装 <code>gh</code>、没登录或没有权限时不弹卡片，链接照常可以点开。</p><h2 id="盯-pr" tabindex="-1">盯 PR <a class="header-anchor" href="#盯-pr" aria-label="Permalink to &quot;盯 PR&quot;">​</a></h2><p>建好 PR 后可以让它盯着：</p><ul><li>每 50 分钟查一次 CI、冲突、评审和评论，有变化弹通知；</li><li>打开自动修复时，CI 失败、出现冲突或评审要求修改，会在原对话里自动开一轮修复（每个 PR 最多 5 轮，操作照常确认）；</li><li>PR 合并或关闭后自动停止，最多盯 14 天。</li></ul><p>GitHub 操作用的是你电脑上的 <code>gh</code> 和你自己的 GitHub 登录，令牌不经过公司服务器。</p><h2 id="子代理-it-开启后才有" tabindex="-1">子代理（IT 开启后才有） <a class="header-anchor" href="#子代理-it-开启后才有" aria-label="Permalink to &quot;子代理（IT 开启后才有）&quot;">​</a></h2><p>复杂任务里，AI 可以临时开子代理去翻代码、查资料：几个只读子代理可以同时跑，能改东西的一次一个，每个操作照常确认。</p><p>每个子代理有自己的上下文：它翻过的文件、跑过的命令不会塞满主对话，主 AI 只拿到它交回的结论，所以适合「同时摸清三个模块」这类大任务。编码模式的任务看板上能看到每个子代理在做什么。</p><h3 id="给子代理换模型" tabindex="-1">给子代理换模型 <a class="header-anchor" href="#给子代理换模型" aria-label="Permalink to &quot;给子代理换模型&quot;">​</a></h3><p>IT 在后台启用了多个模型时，AI 可以给每个子代理选不同的模型：简单的查找、整理用便宜快的，难的推理用强的。能选的就是你在输入框里能选的那些（还要能调用工具）。也可以直接跟 AI 说「用某某模型开子代理去查」。</p><h3 id="项目里定义好的子代理" tabindex="-1">项目里定义好的子代理 <a class="header-anchor" href="#项目里定义好的子代理" aria-label="Permalink to &quot;项目里定义好的子代理&quot;">​</a></h3><p>把常用的分工写成文件放进项目，AI 可以按名字派，不用每次都交代一遍。文件放在工作区根目录的 <code>.flyknit/agents/</code> 下，一个子代理一个 <code>.md</code> 文件：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: reviewer</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: 改完代码后做代码审查，找 bug 和不符合约定的地方</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model: 强模型          # 可选：后台启用的模型名，不填用主 AI 的模型</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">read_only: true        # 可选，默认 true（只能看，不能改）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools: read_file, list_dir, grep   # 可选：只给这些工具</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你是代码审查员：只找 bug 和不符合项目约定的地方，按严重程度排好，写清文件:行号。</span></span></code></pre></div><ul><li>写好后跟 AI 说「改完让 reviewer 审查一下」就行；每次发消息时重新读取，改了马上生效。</li><li>这些文件只能<strong>收窄</strong>子代理能做的事：工具只能从 AI 本来就有的里面挑，<code>read_only: false</code> 时每个改动照样要你确认。</li><li>写着「忽略之前的规则」这类像在给 AI 下指令的文件不会被采用；最多读 20 个文件，每个不超过 8000 字。</li><li>文件跟着项目走，可以提交到代码库，整个开发组共用。</li></ul>`,26)])])}const g=t(d,[["render",l]]);export{u as __pageData,g as default};
